cat << 'EOF' | node > /workspace/docs/sales_summary.txt
const fs = require('fs');
const lines = fs.readFileSync('/workspace/data/sales_q3.csv', 'utf-8').trim().split('\n');
const headers = lines[0].split(',');
const rows = lines.slice(1).map(l => {
  const cols = l.split(',');
  return Object.fromEntries(headers.map((h, i) => [h, cols[i]]));
});

let totalRevenue = 0, won = 0, lost = 0, pending = 0;
const dealsByRegion = {}, revenueByRegion = {};

for (const row of rows) {
  const amount = parseFloat(row.amount);
  const region = row.region;
  const status = row.status;
  dealsByRegion[region] = (dealsByRegion[region] || 0) + 1;
  if (status === 'won') {
    totalRevenue += amount;
    revenueByRegion[region] = (revenueByRegion[region] || 0) + amount;
    won++;
  } else if (status === 'lost') {
    lost++;
  } else {
    pending++;
  }
}

const totalDeals = won + lost + pending;
const winRate = totalDeals ? (won / totalDeals * 100) : 0;

const fmt = n => n.toLocaleString('en-US', { maximumFractionDigits: 0 });
const pad = (s, w) => s + ' '.repeat(Math.max(0, w - s.length));

const sep = '='.repeat(45);
const out = [];
out.push(sep);
out.push('  Meridian Analytics — Q3 Sales Summary');
out.push(sep);
out.push(`  Total deals worked : ${totalDeals}`);
out.push(`  Won                : ${won}`);
out.push(`  Lost               : ${lost}`);
out.push(`  Pending            : ${pending}`);
out.push(`  Win rate           : ${winRate.toFixed(1)}%`);
out.push(`  Total revenue (won): $${fmt(totalRevenue)}`);
out.push('');
out.push('  Revenue by region (won deals):');

const sorted = Object.entries(revenueByRegion).sort((a, b) => b[1] - a[1]);
for (const [region, rev] of sorted) {
  const revStr = ('$' + fmt(rev)).padStart(11);
  out.push(`    ${region.padEnd(8)} ${revStr}  (${dealsByRegion[region]} deals total)`);
}
out.push(sep);
console.log(out.join('\n'));
EOF
